Item.method_code:
let ProcessItem = parent.item;
let processID;
try {
	processID = ProcessItem.getAttribute('id');
} catch {
  // supress error
}

if (!processID) {return;}

ProcessItem = aras.getItemById('Workflow Process',processID);
if (!(ProcessItem)) {return;}
const ProcessTypeID = ProcessItem.getAttribute('type');
const report = aras.getItemByKeyedName('Report','Workflow Process History');
return aras.runReport(report, ProcessTypeID, ProcessItem);
